-- migrate: privileged
-- Roles carry no password: deployment sets credentials. Runs as the privileged connection, not as the owner.
DO $roles$
DECLARE role_name text;
BEGIN
  FOREACH role_name IN ARRAY ARRAY['machvon_owner', 'machvon_app', 'machvon_control', 'machvon_outbox_relay', 'machvon_reporting', 'machvon_sync'] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = role_name) THEN
      EXECUTE format('CREATE ROLE %I LOGIN NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE', role_name);
    END IF;
  END LOOP;
END
$roles$;

-- The owner runs migrations: it needs CREATE on the database for the schema and trusted extensions.
DO $database$
BEGIN
  EXECUTE format('GRANT CONNECT, CREATE ON DATABASE %I TO machvon_owner', current_database());
  EXECUTE format('GRANT CONNECT ON DATABASE %I TO machvon_app, machvon_control, machvon_outbox_relay, machvon_reporting, machvon_sync', current_database());
END
$database$;

CREATE SCHEMA IF NOT EXISTS machvon AUTHORIZATION machvon_owner;
ALTER SCHEMA machvon OWNER TO machvon_owner;
GRANT USAGE ON SCHEMA machvon TO machvon_app, machvon_control, machvon_outbox_relay, machvon_reporting, machvon_sync;

ALTER DEFAULT PRIVILEGES FOR ROLE machvon_owner IN SCHEMA machvon GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO machvon_app;
ALTER DEFAULT PRIVILEGES FOR ROLE machvon_owner IN SCHEMA machvon GRANT USAGE, SELECT ON SEQUENCES TO machvon_app;
